128	impl Node {
129	    /// This node and its descendants, depth first, left to right, each with its path of
130	    /// ancestors from the root.
131	    pub fn walk(&self) -> Vec<(Vec<&Node>, &Node)> {
132	        let mut out = Vec::new();
133	        let mut stack: Vec<(Vec<&Node>, &Node)> = vec![(Vec::new(), self)];
134	        while let Some((path, node)) = stack.pop() {
135	            for child in node.children.iter().rev() {
136	                let mut down = path.clone();
137	                down.push(node);
138	                stack.push((down, child));
139	            }
140	            out.push((path, node));
141	        }
142	        out
143	    }
144	}
