179	/// The lines of a "Where this fits" note for page `id`: each step from the main result down
180	/// to the one the page presents, or the steps that rely on the page's concept. `link` turns
181	/// a page id into a markdown link, or `None` for a page not shown.
182	pub fn trail(argument: &Argument, id: &str, link: &dyn Fn(&str) -> Option<String>) -> Vec<String> {
183	    let on = |n: &Node| {
184	        n.page
185	            .as_deref()
186	            .filter(|p| *p != id)
187	            .and_then(link)
188	            .map_or(String::new(), |l| format!(" ({l})"))
189	    };
190	    match argument.module(id) {
191	        Some((path, node)) if !path.is_empty() => {
192	            let mut lines: Vec<String> = path
193	                .iter()
194	                .enumerate()
195	                .map(|(i, a)| {
196	                    let how = a
197	                        .method
198	                        .as_deref()
199	                        .map_or(String::new(), |m| format!(" — how: {m}"));
200	                    format!("{}. {}{how}{}", i + 1, a.claim, on(a))
201	                })
202	                .collect();
203	            lines.push(format!("{}. **This page:** {}", path.len() + 1, node.claim));
204	            lines
205	        }
206	        Some(_) => Vec::new(),
207	        None => argument
208	            .users(id)
209	            .iter()
210	            .map(|n| format!("- Relied on to show: {}{}", n.claim, on(n)))
211	            .collect(),
212	    }
213	}
