215	/// The top two levels of the argument, as markdown: the main claim, its method and
216	/// motivation, and the steps it splits into.
217	pub fn overview(argument: &Argument, link: &dyn Fn(&str) -> Option<String>) -> String {
218	    let root = &argument.root;
219	    let mut out = format!("**Main result:** {}\n\n", root.claim.trim());
220	    if let Some(method) = &root.method {
221	        out.push_str(&format!("**How:** {}", method.trim()));
222	        if let Some(m) = &root.motivation {
223	            out.push_str(&format!(" **Why:** {}", m.text.trim()));
224	        }
225	        out.push_str("\n\n");
226	    }
227	    for (i, child) in root.children.iter().enumerate() {
228	        let how = child
229	            .method
230	            .as_deref()
231	            .map_or(String::new(), |m| format!(" — how: {m}"));
232	        let on = child
233	            .page
234	            .as_deref()
235	            .and_then(link)
236	            .map_or(String::new(), |l| format!(" ({l})"));
237	        out.push_str(&format!("{}. {}{how}{on}\n", i + 1, child.claim));
238	    }
239	    out
240	}
