390	fn check(
391	    graph: &Graph,
392	    plan: &Plan,
393	    sources: &[Source],
394	    root: &Node,
395	) -> (Vec<String>, Vec<String>) {
396	    let nodes = root.walk();
397	    let position_of: HashMap<&str, usize> = plan
398	        .order
399	        .iter()
400	        .enumerate()
401	        .map(|(i, p)| (p.as_str(), i))
402	        .collect();
403	    let mut errors = Vec::new();
404	    let mut warnings = Vec::new();
405	
406	    // 1. The root.
407	    if root.intention != Intention::Show {
408	        errors.push("the root must be a `show` step".into());
409	    }
410	    if root.page.as_deref() != Some(graph.goal()) {
411	        errors.push(format!(
412	            "the root's page must be the target page `{}`",
413	            graph.goal()
414	        ));
415	    }
416	
417	    let mut ids = HashSet::new();
418	    let mut pages: HashMap<&str, &str> = HashMap::new();
419	    for (path, n) in &nodes {
420	        let what = format!("step `{}`", n.id);
421	        if n.id.trim().is_empty() {
422	            errors.push(format!("a step with claim \"{}\" has no id", n.claim));
423	        } else if !ids.insert(n.id.as_str()) {
424	            errors.push(format!("{what} appears twice"));
425	        }
426	        if n.claim.trim().is_empty() {
427	            errors.push(format!("{what} has no claim"));
428	        }
429	        // 3. Structure.
430	        match n.intention {
431	            Intention::Show => {
432	                if n.children.is_empty() {
433	                    errors.push(format!(
434	                        "{what} is a show step with no sub-steps; make it an infer step with \
435	                         a quote, or give its sub-steps"
436	                    ));
437	                }
438	                if n.method.as_deref().is_none_or(|m| m.trim().is_empty()) {
439	                    errors.push(format!("{what} has no method"));
440	                }
441	                match &n.motivation {
442	                    None => errors.push(format!("{what} has no motivation")),
443	                    Some(m) => {
444	                        if m.text.trim().is_empty() {
445	                            errors.push(format!("{what}: the motivation is empty"));
446	                        }
447	                        match (&m.quote, m.source) {
448	                            (Some(q), _) => check_quote(
449	                                sources,
450	                                q,
451	                                &format!("{what}'s motivation"),
452	                                &mut errors,
453	                            ),
454	                            (None, Provenance::Explicit) => errors.push(format!(
455	                                "{what}: an explicit motivation needs a quote from the sources"
456	                            )),
457	                            (None, _) => {}
458	                        }
459	                    }
460	                }
461	            }
462	            Intention::Infer => {
463	                if !n.children.is_empty() {
464	                    errors.push(format!(
465	                        "{what} is an infer step with sub-steps; make it a show step"
466	                    ));
467	                }
468	                match &n.quote {
469	                    None => errors.push(format!(
470	                        "{what} is an infer step with no quote from the sources"
471	                    )),
472	                    Some(q) => check_quote(sources, q, &what, &mut errors),
473	                }
474	            }
475	        }
476	        // 5. Modules.
477	        if let Some(page) = &n.page {
478	            if !position_of.contains_key(page.as_str()) {
479	                errors.push(format!("{what}: `{page}` is not a page of this wiki"));
480	            } else if let Some(other) = pages.insert(page, &n.id) {
481	                errors.push(format!(
482	                    "`{page}` presents both step `{other}` and {what}; give a page one step"
483	                ));
484	            }
485	        }
486	        // 4. Hypotheses, against the step's page: its own or its nearest ancestor's.
487	        let page = std::iter::once(*n)
488	            .chain(path.iter().rev().copied())
489	            .find_map(|a| a.page.as_deref())
490	            .and_then(|p| position_of.get(p).map(|&i| (p, i)));
491	        for f in &n.from {
492	            match graph.get(f) {
493	                None => errors.push(format!("{what}: `{f}` in `from` is not a concept id")),
494	                Some(c) if c.known => {}
495	                Some(c) => match (position_of.get(c.id.as_str()), page) {
496	                    (None, _) => errors.push(format!(
497	                        "{what}: `{f}` in `from` is neither known nor a page of this wiki"
498	                    )),
499	                    (Some(&i), Some((p, at))) if i >= at => errors.push(format!(
500	                        "{what}: `{f}` in `from` does not come before the step's page `{p}` in \
501	                         the reading order"
502	                    )),
503	                    _ => {}
504	                },
505	            }
506	        }
507	        let below: Vec<String> = n
508	            .walk()
509	            .iter()
510	            .flat_map(|(_, d)| symbols::math(&d.claim))
511	            .collect();
512	        for b in &n.adds {
513	            if !symbols::occurs(&b.symbol, &below) {
514	                errors.push(format!(
515	                    "{what}: `{}` in `adds` occurs in none of the claims at or below it",
516	                    b.symbol
517	                ));
518	            }
519	        }
520	        // A step's page reads before its ancestors' pages, as the target comes last.
521	        if let Some(page) = &n.page
522	            && let Some(&at) = position_of.get(page.as_str())
523	        {
524	            for a in path {
525	                if let Some(above) = &a.page
526	                    && position_of.get(above.as_str()).is_some_and(|&i| i < at)
527	                {
528	                    warnings.push(format!(
529	                        "step `{}` is presented on `{page}`, which comes after `{above}`, the \
530	                         page of the step it serves: readers meet the step's use before the \
531	                         step",
532	                        n.id
533	                    ));
534	                }
535	            }
536	        }
537	    }
538	
539	    // 2. Report order.
540	    let mut last: Option<((usize, usize), &str)> = None;
541	    for (_, n) in &nodes {
542	        if n.intention != Intention::Infer || n.deferred {
543	            continue;
544	        }
545	        let Some(at) = n.quote.as_ref().and_then(|q| position(sources, q)) else {
546	            continue;
547	        };
548	        if let Some((before, id)) = last
549	            && at < before
550	        {
551	            errors.push(format!(
552	                "step `{}` quotes the sources before step `{id}`, which comes earlier in the \
553	                 plan: the sources report the plan depth first, so reorder the steps, or mark \
554	                 `{}` deferred if the sources report it out of order",
555	                n.id, n.id
556	            ));
557	        }
558	        last = Some((at, &n.id));
559	    }
560	
561	    let used: HashSet<&str> = nodes
562	        .iter()
563	        .flat_map(|(_, n)| n.page.iter().chain(&n.from).map(String::as_str))
564	        .collect();
565	    let unused: Vec<&str> = plan
566	        .order
567	        .iter()
568	        .map(String::as_str)
569	        .filter(|p| !used.contains(p))
570	        .collect();
571	    if !unused.is_empty() {
572	        errors.push(format!(
573	            "pages that neither present a step nor appear in a step's `from`: {}",
574	            unused.join(", ")
575	        ));
576	    }
577	
578	    (errors, warnings)
579	}
